cd /app && cat > /tmp/check.js << 'EOF'
const raw = require('fs').readFileSync('/app/out.json','utf8');
const o = JSON.parse(raw);
const keys = Object.keys(o);
let okInt = true, okKey = true, okRange = true;
let min = Infinity, max = -Infinity;
for (const k of keys) {
  const v = o[k];
  if (typeof v !== 'number' || !Number.isInteger(v)) okInt = false;
  if (!/^\d+$/.test(k)) okKey = false;
  if (v < 0 || v > 0xffffffff) okRange = false;
  if (v < min) min = v;
  if (v > max) max = v;
}
console.log('entries:', keys.length);
console.log('all values integer numbers:', okInt);
console.log('all keys decimal strings:', okKey);
console.log('all values in [0, 2^32-1]:', okRange);
console.log('min value:', min, 'max value:', max);
// uniqueness of keys
console.log('unique keys:', new Set(keys).size === keys.length);
EOF
node /tmp/check.js

